#!/usr/bin/env python3
"""Generate ADR files from a single data table. Run: python3 scripts/gen_adrs.py"""
import os

BASE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
OUT = os.path.join(BASE, "decisions")

ADRS = [
(1, "Oracle Linux and Ubuntu Server standardization",
 "Both are required by the master prompt. Full standardization on one distro would reduce test surface but conflicts with the stated requirement and with hardware/support realities (GPU driver availability, enterprise support contracts).",
 ["Support both with a shared control plane, but keep OS-specific playbooks separate.",
  "Standardize on one distro and mirror it elsewhere.",
  "Standardize on one and drop the other."],
 "Support both. Common automation is factored into shared roles; distro-specific behaviour lives in separate role directories with distinct package names, paths, security modules, and service managers.",
 ["Boring: one control plane, two well-tested variants.",
  "Twice the OS test surface.",
  "SELinux vs AppArmor both need policy work."],
 "Security posture differs: SELinux is more granular and blocks more by default (container runtimes need explicit labeling); AppArmor is path-based, more permissive by default, easier to break silently.",
 "Ubuntu 22.04/24.04 LTS and Oracle Linux 8/9 (both have long support windows; exact supported releases must be confirmed against Kubespray's supported-OS list at the pinned release).",
 "A node built for one distro is not portable to the other without a rebuild. Nodes are disposable and rebuilt by Ansible, so a rebuild is a routine operation, not an incident.",
 "Standardization on a single distro would halve OS-level test effort, but drops a mandated platform and risks unsupported hardware paths. The mitigation is a shared-role factoring discipline."),

(2, "Kubernetes control-plane topology",
 "Control-plane size drives API availability, etcd quorum, and cost. Master prompt asks for 5 as preferred reference, 3 as minimum production.",
 ["3 control-plane nodes with stacked etcd.",
  "5 control-plane nodes with stacked etcd.",
  "3 control-plane nodes with dedicated etcd on 3 separate nodes."],
 "3 control-plane nodes with stacked etcd for the first environment; 5 documented as the reference production topology for larger sites. Revisit when sustained API load or a third failure domain justifies it.",
 ["3 nodes tolerate 1 control-plane failure.",
  "5 nodes tolerate 2, but 5 stacked etcd members on 5 nodes still lose quorum at 3 failures.",
  "5 nodes cost more and lengthen every maintenance window."],
 "Each control-plane node runs kube-apiserver, kube-controller-manager, kube-scheduler, etcd, and the CNI agent. etcd members are colocated on control-plane nodes: a node loss takes one member and one API replica together.",
 "5 stacked-etcd members in 3 failure domains is possible but raises quorum sensitivity to correlated failures; dedicated etcd is cleaner but adds 3+ nodes.",
 "etcd is the state store for all cluster state. Loss of quorum stops all API writes immediately; running pods keep their state.",
 "Kubespray supports both topologies; dedicated etcd requires a separate inventory group and more careful host preparation. A later migration from stacked to dedicated etcd means etcd data migration, not a simple role change.",
 "Fewer nodes to patch, drain, and replace, and lower etcd write-latency exposure. 5 nodes are justified only by API load or by a real third failure domain."),

(3, "etcd placement",
 "etcd holds all cluster state. Its failure characteristics dominate cluster recovery.",
 ["Stacked on control-plane nodes.",
  "Dedicated hosts.",
  "Dedicated managed service (out of scope offline)."],
 "Stacked on control-plane nodes in the first environment. Dedicated etcd hosts become mandatory when the site has separate failure domains for control-plane and storage-heavy workloads, or when etcd disk latency threatens API latency.",
 ["Fewer nodes, lower cost.",
  "etcd gets dedicated fast local disks.",
  "Best isolation, highest cost."],
 "etcd traffic is sensitive to disk latency and network jitter. Colocating etcd with the API server means a slow disk degrades both.",
 "3 or 5 members spread across the failure domains available. 3 members tolerate 1 failure, 5 tolerate 2.",
 "Total etcd quorum loss halts all cluster writes. Restore is from a snapshot; recovery time is dominated by snapshot size and restore bandwidth.",
 "Migrating from stacked to dedicated etcd is a data migration performed by the Kubespray workflow with the dedicated-etcd inventory; it is not a role flip.",
 "Stacking is the standard, supported, simplest path. Dedicated etcd pays off when disks or failure domains justify it."),

(4, "Load balancing for control plane and ingress",
 "kube-apiserver, Rancher, Argo CD, Keycloak, and ingress all need stable virtual IPs that fail over. The requirement is an active/active pair of Linux edge nodes running Nginx or HAProxy with Keepalived, deployed with Docker Compose. Superseded in detail by ADR-0028, which defines the tiered design; this record states the boundary between the edge and the in-cluster load balancing.",
 ["Hardware F5/HA pair.",
  "Keepalived (VRRP) on a pair of nodes.",
  "HAProxy in a small dedicated pair."],
 "Keepalived VRRP on two dedicated edge nodes for the control-plane API VIP, with an HAProxy or NGINX layer in front for TLS termination and upstream health checks. Hardware F5 only if the site already owns one. The full external load balancer design, including the active/active tiers, is in ADR-0028 and network-matrix/external-load-balancer.md.",
 ["VRRP failover is in the second range, not instant.",
  "HAProxy is explicit and scriptable.",
  "Hardware gives the best support path.",
  "A single VRRP-owned VIP is active/standby, so the active/active requirement is met above the VIP layer, not by VRRP itself."],
 "VRRP depends on multicast or unicast peer configuration on the network segment; a switched network with multicast filtering needs unicast peers. HAProxy and keepalived both need health checks against the real backends. The edge is the only host exposed to the untrusted segment, so it runs a minimal image set and allows only 80 and 443 inbound.",
 "VRRP protocol 112 (IP protocol), keepalived health-check ports, HAProxy frontend/backend ports, and the management-only stats port. Verify against the installed versions.",
 "A VIP with no working failover is worse than no VIP: it hides a single point of failure behind a stable address. A split-brain VIP (both nodes think they are master) causes intermittent failures.",
 "Migrating from keepalived to HAProxy or to hardware is a config change, not a data migration. Moving from tier 1 to the active/active tier 2 needs router ECMP or BGP for the second VIP, as described in ADR-0028.",
 "Keepalived is a small, well-understood dependency and can be managed by Ansible. Hardware is preferred where it exists."),

(5, "Container runtime",
 "Kubespray supports containerd, Docker, and CRI-O. The runtime must match the offline image distribution design and the GPU stack.",
 ["containerd.",
  "Docker (via cri-dockerd).",
  "CRI-O."],
 "containerd. It is the upstream default, has native registry mirror/TLS configuration, and is the runtime the NVIDIA Container Toolkit integrates with.",
 ["Native image pull policy, no daemon socket privilege.",
  "Docker adds a socket and a shim layer.",
  "CRI-O is fine but less common in offline images."],
 "containerd is the component that holds the registry trust and mirror configuration, so it is also the security-relevant choice for offline operation.",
 "containerd API/registry config paths and the CRI plugin version. Verify against the pinned Kubespray release and the containerd release notes.",
 "A broken containerd config takes down image pulls on the node, but running containers keep running until they need to restart.",
 "Switching runtimes means rebuilding nodes. Kubespray supports it but it is a node-level operation, not a live migration.",
 "containerd is the boring, supported default with the cleanest offline-mirror story."),

(6, "CNI selection",
 "CNI defines pod networking, network policy, and integration with load balancing and service meshes.",
 ["Calico.",
  "Cilium.",
  "Flannel."],
 "Cilium. eBPF datapath, Hubble observability, L7 network policy, native integration with MetalLB, and no kube-proxy dependency, which removes a class of iptables scaling problems.",
 ["eBPF performance, L7 policy, Hubble, kube-proxy-free.",
  "Calico is mature with more third-party integrations.",
  "Flannel has no network policy."],
 "Cilium's eBPF datapath needs a compatible kernel and, for some features, specific kernel versions. It creates a wider kernel-compatibility envelope than Calico.",
 "Cilium agent and operator ports, Hubble relay/metrics, the agent's health and metrics ports. Verify against the pinned Cilium release.",
 "A CNI failure takes down pod-to-pod connectivity for everything on the node, and can make existing pods unreachable. This is one of the highest-blast-radius components.",
 "Swapping CNI requires draining and recreating pods (pod IP and connectivity change), and re-validating network policy. There is no in-place conversion.",
 "Cilium gives the most capability with the least extra infrastructure, and Hubble materially helps troubleshooting. Calico remains the fallback if kernel constraints bite."),

(7, "Ingress controller and Gateway API",
 "L7 traffic entry, TLS termination, and routing. The community ingress-nginx project (kubernetes/ingress-nginx) was retired in March 2026 with no further releases or security fixes, so the previously default choice is no longer adoptable. The successor options are F5's NGINX Ingress Controller (nginx/kubernetes-ingress), F5's NGINX Gateway Fabric (Gateway API native), and Traefik.",
 ["F5 NGINX Ingress Controller (nginx/kubernetes-ingress).",
  "F5 NGINX Gateway Fabric.",
  "Traefik.",
  "Retain the retired kubernetes/ingress-nginx."],
 "F5 NGINX Ingress Controller as the L7 controller, with Gateway API objects adopted for new applications and Ingress retained for compatibility. Re-evaluate toward NGINX Gateway Fabric when Gateway API becomes the only API in use across the estate.",
 ["F5-maintained with a commercial support path; mature TLS handling; NGINX dataplane; supports both Ingress and Gateway API.",
  "NGINX Gateway Fabric is Gateway API native and is the vendor's forward path, but it requires converting every Ingress resource before it can serve them.",
  "Traefik is simpler and label-driven but has a smaller enterprise support ecosystem.",
  "Retaining the retired controller leaves the platform with no security fixes and a read-only repository; the steering committee has stated that doing so leaves users vulnerable."],
 "The controller must be hardened: no unnecessary NGINX modules, explicit worker and connection limits, and admission webhooks that do not permit arbitrary configuration injection from untrusted namespaces. The retired project was explicitly criticised for the snippets annotation allowing arbitrary NGINX directives, so the replacement must not reintroduce that surface.",
 "NGINX Ingress Controller controller, webhook, and metrics ports; Gateway API CRDs are client-side only. For NIC 5.7.0 the officially tested Kubernetes range is 1.30-1.37, with Helm chart 2.8.0 and operator 3.8.0. NGINX Gateway Fabric 2.8.0 is conformant with Gateway API 1.6.3 and requires Kubernetes 1.32+. Verify against the pinned release.",
 "Ingress controller failure affects all external traffic to the cluster, but internal ClusterIP traffic is unaffected. A Gateway API implementation failure has the same blast radius.",
 "Moving from Ingress to Gateway API is incremental: both can coexist and a Gateway controller can run alongside the Ingress one on a separate address. The Kubernetes SIG Network ingress2gateway tool converts existing Ingress resources to Gateway API, but it is a conversion utility, not an end-to-end migration, so the converted output must be reviewed and tested. Changing the controller is a helm swap with a brief traffic interruption.",
 "The NGINX dataplane and the F5 support path are the deciding factors, not inertia: the NGINX Ingress Controller is a different project from the retired ingress-nginx and is actively maintained by F5."),

(8, "Ceph deployment model",
 "Ceph can be deployed by cephadm on dedicated hosts, by Rook-Ceph inside Kubernetes, or by containerized Ceph under Podman/Docker.",
 ["cephadm on dedicated storage hosts.",
  "Rook-Ceph inside Kubernetes.",
  "Containerized Ceph under Podman/Docker."],
 "Two supported models, used for different purposes: Rook-Ceph inside the Application Cluster for cluster-local storage, and cephadm on dedicated storage hosts for shared capacity consumed by multiple clusters through the external CSI driver. Containerized Ceph under Docker/Podman is explicitly NOT a supported model here — it is neither cephadm nor Rook and carries no upgrade or support path.",
 ["cephadm is the vendor-supported path with clean lifecycle.",
  "Rook gives K8s-native CRDs and CSI integration.",
  "Containerized Ceph is unsupported operationally."],
 "cephadm owns the whole lifecycle including upgrade orchestration; Rook adds an operator layer between K8s and cephadm-style daemons, which shifts the upgrade sequence (Ceph first, then Rook, then CSI).",
 "Ceph MON/OSD/MDS/RGW ports, the CSI driver needs to reach MON and OSD. Rook's operator and CSI images must be mirrored offline.",
 "A Ceph failure that takes out the storage network affects both models. Running Ceph in Kubernetes adds a coupling: a cluster-wide network or CNI failure can take storage with it.",
 "Rook to cephadm is a migration of the whole cluster, not a config change. cephadm to Rook is likewise. Plan the Ceph version before committing to either path.",
 "Using only cephadm for everything means the Application Cluster depends on an external storage cluster for basic PVCs, which is a deliberate choice with a deliberate cost in complexity. Supporting both models covers both needs but doubles the operational surface, so it is accepted only with distinct documentation, monitoring, and upgrade runbooks."),

(9, "Service mesh adoption",
 "The master prompt asks for a mesh evaluation, and the requirement to explain benefits and acceptance criteria.",
 ["Adopt Istio now.",
  "Adopt Linkerd now.",
  "Defer until a threshold is met."],
 "Defer. No mesh in the initial platform. Adopt only when a documented threshold is met: >=30 services requiring mTLS, cross-team traffic policy requirements, and >=2 application clusters. Istio is the first candidate, Linkerd the lighter alternative.",
 ["Istio has the largest feature set and ecosystem.",
  "Linkerd is lighter and simpler.",
  "No mesh means fewer artifacts, less CPU, fewer upgrades."],
 "A mesh adds a sidecar (or ambient) data path, its own control plane, CRDs, and a large artifact set that must all be mirrored offline. It also creates new failure modes: a bad DestinationRule can blackhole traffic.",
 "Istio/Linkerd control plane, sidecar, and gateway ports, plus the Envoy/xDS ports. Verify per release.",
 "Mesh misconfiguration can break service-to-service traffic cluster-wide. The blast radius is larger than any other add-on, and it is silent until traffic is affected.",
 "Removing a mesh later means removing sidecars from every workload and cleaning up CRDs; it is disruptive but not a data migration.",
 "Native Kubernetes networking plus NetworkPolicy covers the current requirement. Adopting a mesh before it is needed adds operational cost with no benefit."),

(10, "Management Cluster design and what runs inside it",
 "The master prompt asks which platform services run in the Management Cluster and which stay outside.",
 ["Everything platform-related in the Management Cluster.",
  "Everything outside, on dedicated hosts.",
  "Split by criticality."],
 "Split by criticality. The Management Cluster runs Rancher, Argo CD, Prometheus, Grafana, Loki, and platform dashboards. It does NOT run Vault, GitLab, the registry, or the artifact repositories — those run on dedicated infrastructure outside Kubernetes so that a cluster loss cannot remove the secrets, source, or images needed to rebuild it.",
 ["Cluster-scoped visibility and control in one place.",
  "Independent services are more work to run.",
  "Split avoids the circular dependency of rebuilding a cluster from tools inside it."],
 "Running Vault inside the cluster it protects is the classic circular dependency: losing the cluster can lock you out of the secrets needed to restore it.",
 "All platform service ports are in the network matrix. Cross-cluster traffic rules: Management -> Application on 6443, Argo CD -> Vault on 8200, and Application -> Harbor on 443.",
 "Management Cluster loss does not stop running workloads. It stops new deployments (Argo CD sync), cluster registration, and dashboards. This is the intended blast radius.",
 "Moving a service out of the Management Cluster later is a deployment change; moving Vault out is a data migration with an unseal procedure.",
 "Keeping the restore-critical services outside the cluster is what makes the rebuild path work. The cost is running a few more plain services on dedicated hosts."),

(11, "Rancher versus alternatives",
 "Multi-cluster management is required; Rancher is the named candidate.",
 ["Rancher.",
  "Cluster API with a management platform.",
  "Plain kubectl plus a config repo."],
 "Rancher as the primary multi-cluster management plane, with Cluster API evaluated later if the fleet exceeds roughly five clusters or if declarative cluster lifecycle becomes a hard requirement.",
 ["Familiar UI, cluster lifecycle, Fleet GitOps, mature RBAC, provisioning integrations.",
  "Cluster API is the upstream standard and strongly declarative.",
  "kubectl alone has no lifecycle story."],
 "Rancher requires its own cluster to run and has license tiers with feature differences that must be checked for the intended use. Cluster API introduces a bootstrap-provider dependency (ClusterClass or CAPD/CAPM3).",
 "Rancher server/agent and webhook ports, plus 6443 to managed clusters. Verify per release.",
 "Rancher loss does not affect workloads or Argo CD sync inside each cluster. It removes cluster registration and Fleet-based provisioning.",
 "Switching from Rancher to Cluster API is a re-platforming of the management layer; clusters themselves survive because Argo CD and the workload state are independent.",
 "Rancher gives the most usable day-2 experience with the least new machinery. Cluster API is the better long-term standard but is not needed at the current fleet size."),

(12, "Ansible GUI platform",
 "Ansible is primary; a GUI is evaluated for approval workflows and audit.",
 ["AWX.",
  "Semaphore UI.",
  "Rundeck."],
 "AWX. It is the closest to the Ansible Automation Platform's open-source core, has built-in RBAC, job approval, scheduling, and audit logging, and consumes the same roles and inventories. Semaphore UI is the lighter alternative. Rundeck is not recommended because it introduces a second job model that is not Ansible-native.",
 ["AWX has the strongest audit and approval story.",
  "Semaphore is simpler and lighter.",
  "Rundeck is a general job runner, not an Ansible UI."],
 "AWX is stateful (PostgreSQL) and therefore needs its own backup and restore path, and it becomes a control-plane component for change management.",
 "AWX web port, PostgreSQL port, and callback/websocket traffic between AWX and target hosts. Verify per release.",
 "AWX loss blocks GUI-driven changes but does not block direct ansible-playbook runs from the automation server, nor Argo CD deployments.",
 "Migrating to Semaphore is a UI swap; the roles and inventories carry over. Migrating to AWX later means re-importing inventories and job templates.",
 "AWX provides the audit trail the change-management model requires, which is the deciding factor."),

(13, "GitLab runner architecture",
 "CI must not endanger the clusters or the registries it deploys to.",
 ["Shell runner on the automation server.",
  "Docker runner on the automation server.",
  "Kubernetes runner inside the cluster.",
  "Dedicated VM runner."],
 "Docker executor on the automation server for build and unit stages, plus a Kubernetes executor in a dedicated `ci` namespace with namespace-scoped service accounts for integration and deploy stages. No shell executor for anything that touches a cluster, and never a runner on a control-plane node.",
 ["Isolation without a second virtualization layer.",
  "Real pod isolation for cluster jobs.",
  "A VM runner isolates the host."],
 "A cluster runner needs an agent token with cluster-scoped power; a misconfigured CI job can then read the whole cluster. The `ci` namespace and a scoped service account reduce that.",
 "Runner -> GitLab 443, runner -> GitLabLab API, runner -> K8s API 6443, runner -> Harbor 443. All in the network matrix.",
 "A compromised runner that holds a cluster-admin token can read every Secret in the cluster. Keep runner tokens short-lived where possible and scope them.",
 "Changing runner type means re-registering runners and updating job tags. Low risk, small operational cost.",
 "Docker on the automation server is the simplest isolation that still protects the host. The cluster runner is scoped and separated so a CI job cannot reach production namespaces."),

(14, "GitOps strategy and division of labour with Ansible",
 "Multiple tools must not fight over the same configuration.",
 ["Argo CD manages everything including cluster add-ons.",
  "Argo CD manages add-ons and applications; Ansible manages OS and cluster lifecycle.",
  "Argo CD for add-ons only; applications deployed by CI."],
 "Argo CD manages Kubernetes-declared state: platform add-ons and application manifests. Ansible owns the operating system, node configuration, Kubespray cluster lifecycle, and external services. GitLab owns source control, validation, approvals, and pipeline execution. Each object has exactly one reconciler.",
 ["Single writer per object avoids drift fights.",
  "Clear mental model for operators.",
  "More tools to learn."],
 "Overlapping ownership causes Argo CD to revert manual changes and Ansible to overwrite Helm-managed state. The ownership table in the CI design doc is normative.",
 "Argo CD -> GitLab 443, Argo CD -> K8s API 6443, Argo CD -> Vault 8200 (if using plugin-based secret management).",
 "Argo CD loss stops automated sync but does not stop running workloads. Ansible-driven changes continue.",
 "Moving an object to a different owner is a one-time change in the Argo CD exclusion list or the Ansible role, plus a Git move.",
 "One writer per object is the only way multi-tool estates stay stable. The boundary between node-level and cluster-level state is the natural line."),

(15, "Linux directory integration",
 "Servers must work both standalone and AD-integrated, with a migration path.",
 ["Local accounts only.",
  "SSSD with AD or LDAP as the identity source, with local break-glass accounts retained.",
  "Full AD join via realmd."],
 "SSSD as the mechanism (it handles both AD and LDAP providers) with realmd available for the AD join flow, plus mandatory local break-glass accounts and an emergency SSH key held offline on every node.",
 ["Single mechanism for two directory types.",
  "SSSD caches identity and allows offline login.",
  "realmd is a convenience wrapper for the AD join."],
 "SSSD caches credentials, so a revoked or locked AD account can still log in for the cache lifetime. Cache timeout is a security decision, not a default. UID/GID mapping from AD can collide with local accounts.",
 "Kerberos 88, LDAP 389/636, DNS 53, NTP 123. SSSD communicates with the KDC and DC.",
 "Directory outage stops new logins but does not stop running workloads. Break-glass accounts remain the recovery path.",
 "Migration from local accounts to SSSD is straightforward and reversible; the reverse migration requires re-creating local accounts. UID/GID mismatch can break file ownership on existing data, notably on Ceph OSD directories.",
 "SSSD is the standard mechanism and the only one that gives a workable offline-cache story. Break-glass accounts are non-negotiable in an air-gapped environment where the directory may be unreachable."),

(16, "Vault deployment model",
 "Secrets must survive the loss of the cluster they protect.",
 ["Inside the Management Cluster.",
  "Inside a dedicated separate Kubernetes cluster.",
  "On dedicated Linux hosts."],
 "On dedicated Linux hosts, 3 nodes, integrated Raft storage. Unseal material held offline. Vault is never deployed inside the Management Cluster.",
 ["Independent of every cluster failure.",
  "No admission or scheduling problems.",
  "Manual HA management, no Helm chart."],
 "Running Vault in-cluster means a cluster outage can lock you out of the secrets needed to restore it. The unseal path would depend on the same infrastructure that failed.",
 "8200 (API), 8201 (cluster, raft), 8202 (HA redirect/clustering), plus the unseal/KMS endpoint. Verify per release.",
 "Vault down means: no new secret issuance, no rotation, no certificate renewal. Running workloads are unaffected unless they read secrets at startup. Applications that need renewed secrets will fail on the next renewal cycle unless they can tolerate the outage.",
 "Migrating Vault from hosts into a cluster is a supported but non-trivial move involving the storage backend and the unseal configuration. Keep the host deployment as the long-term state.",
 "Host deployment is the only model that has no circular dependency with the cluster. The cost is a small amount of manual HA configuration that Ansible absorbs."),

(17, "PKI and certificate ownership",
 "TLS is required everywhere, offline, with renewal.",
 ["cert-manager with an internal CA.",
  "cert-manager with Vault PKI.",
  "External enterprise CA with an ACME/EST bridge."],
 "cert-manager as the Kubernetes-side issuer and renewer, backed by Vault PKI for the internal CA, with the root CA key stored offline. Enterprise CA integration is supported if the site owns one, via a documented bridge.",
 ["One renewal engine in the cluster.",
  "Vault PKI keeps the CA key inside the secrets manager.",
  "An enterprise CA centralizes policy across non-K8s systems."],
 "An internal CA means trust must be distributed to every client (OS trust store, container images, Java keystores). Missing trust distribution is the most common cause of offline TLS failures. If a Vault outage stops issuance, renewals fail at the CA layer and that path needs to be documented.",
 "Vault 8200, cert-manager webhook 6443, ACME/EST port as configured. Verify per release.",
 "CA unavailability stops issuance and renewal. Existing certificates keep working until expiry, so expiry alerting is mandatory.",
 "Root CA rotation is a multi-step process with no instant cutover: issue a new intermediate, move issuance, wait for leaves to expire, revoke the old intermediate. It is not a single command.",
 "Vault PKI plus cert-manager gives automated renewal with the CA key protected, and Vault is already required for secrets. The trust distribution burden is real and is handled by the OS baseline."),

(18, "Monitoring platform and long-term metrics",
 "Prometheus is mandatory; long-term retention and cross-cluster views need a decision.",
 ["Prometheus only.",
  "Prometheus + Thanos.",
  "Prometheus + VictoriaMetrics."],
 "Prometheus Operator with kube-prometheus-stack, and Thanos sidecar for long-term retention and cross-cluster queries once retention exceeds about 30 days or more than one cluster is monitored. VictoriaMetrics is the alternative if cost becomes a driver.",
 ["Thanos is the ecosystem standard and integrates with kube-prometheus-stack.",
  "VictoriaMetrics uses less resource and stores more per byte.",
  "Prometheus alone is simplest but retains only as long as local disk allows."],
 "Thanos adds object-storage coupling and a sidecar per Prometheus. VictoriaMetrics is a different operational model with its own consistency semantics.",
 "Prometheus 9090, node_exporter 9100, kube-state-metrics 8080, Alertmanager 9093, Thanos sidecar/UI ports. Verify per exporter release.",
 "Monitoring outage does not affect workloads. Losing the object storage breaks long-term queries and Thanos compaction but not live metrics.",
 "Switching from Thanos to VictoriaMetrics means re-pointing the query layer and re-importing historical data. Do it while the data volume is still small.",
 "Thanos is the boring choice that matches the existing operator stack."),

(19, "Centralized logging backend",
 "Central logs are needed for audit, troubleshooting, and security detection.",
 ["Loki + Fluent Bit.",
  "OpenSearch + Fluent Bit/Logstash.",
  "Elasticsearch + Logstash + Kibana."],
 "Loki with Fluent Bit as the default backend, with OpenSearch added only where full-text search across log content is a hard requirement (audit investigation, compliance). Elasticsearch is avoided in favour of OpenSearch on licensing grounds, subject to a licence review.",
 ["Loki is far cheaper and label-based, and it fits Kubernetes metadata well.",
  "OpenSearch gives full-text, SQL, and alerting on content.",
  "Elasticsearch is the most capable but the most resource-hungry and licence-encumbered."],
 "Loki's label model is index-like: high-cardinality labels (pod UID, request id) destroy performance. Label cardinality must be a design constraint, not a discovery.",
 "Fluent Bit forwarder to the backend, Loki 3100, OpenSearch 9200, Logstash 5044, and Fluent Bit OTLP 4317/4318. Verify per release.",
 "Log ingestion failure does not affect workloads unless a workload writes to stdout/blocked logging, which must be avoided with bounded buffers.",
 "Migrating from Loki to OpenSearch means re-indexing historical logs. Keep the Fluent Bit output layer abstracted so the backend can change without touching nodes.",
 "Loki is the pragmatic default for Kubernetes-native logs. OpenSearch is added as a targeted capability rather than a platform-wide default."),

(20, "Security policy engine",
 "Admission control and runtime detection are required.",
 ["OPA Gatekeeper only.",
  "Kyverno only.",
  "Both, with a defined split."],
 "Both, with a defined split: OPA Gatekeeper for constraint validation expressed in Rego (complex cross-resource rules, quotas, allowed-registries), Kyverno for image and resource policies that teams can write directly in YAML without learning Rego.",
 ["Rego is powerful and testable.",
  "Kyverno policies are readable by application teams.",
  "One engine means one webhook and one failure mode."],
 "Two admission engines mean two webhooks on the API path and two failure policies. A misconfigured webhook can block all deployments. Both must be deployed in audit mode first, then switched to enforce, and both must be excluded from the platform's own namespaces.",
 "Webhook ports (typically 443 via the apiserver), Gatekeeper controller and manager ports, Kyverno admission/background/cleanup/report ports. Verify per release.",
 "A broken admission webhook can block all writes to the cluster. FailurePolicy must be configured deliberately: Fail for security namespaces, Ignore for the platform namespaces, with a documented exception process.",
 "Removing one engine means deleting its constraints and webhook configuration, then re-validating that the remaining engine covers the policies that were dropped.",
 "The split avoids forcing every team to learn Rego while keeping the power of Rego for platform-wide constraints. It is accepted with the cost of two webhooks explicitly documented."),

(21, "GPU worker architecture and isolation",
 "GPU workers are expensive and have distinct failure modes.",
 ["Shared general worker pool with GPU nodes added to it.",
 "Dedicated GPU worker pool with taints and labels.",
 "Dedicated GPU hosts outside Kubernetes."],
 "Dedicated GPU worker pool: GPU nodes form their own node pool with a `nvidia.com/gpu` taint, their own network segment, and their own resource quota. Non-GPU workloads cannot land there by default; GPU workloads require an explicit toleration.",
 ["No noisy-neighbour impact on CPU/memory workloads.",
  "Isolated failure and upgrade domain.",
  "Explicit capacity accounting for GPU hours."],
 "Dedicated pools consume some scheduling efficiency: a GPU node with a free GPU but no tolerating pod sits idle. Mitigated with a controlled burst policy allowing a non-GPU workload class to tolerate the GPU taint.",
 "GPU node -> API 6443, DCGM exporter 9400, model store 443, node-to-node NVLink/PCIe is local traffic, and the NVIDIA container runtime talks to the driver locally.",
 "A GPU node loss removes that capacity and may interrupt in-flight inference requests. Clients must handle connection resets and retry.",
 "Converting a general node into a GPU node is a hardware change and a node rebuild. Keeping a small, separately-managed general pool for burst removes the scheduling dead time.",
 "Dedicated GPU pools are the standard practice for inference fleets and keep the AI capacity predictable."),

(22, "GPU sharing strategy",
 "One physical GPU serving several tenants needs an isolation decision.",
 ["MIG.",
  "Time-slicing.",
  "MPS.",
  "Exclusive allocation only."],
 "MIG for production multi-tenancy, exclusive allocation for maximum throughput, and time-slicing strictly limited to development and burst use. MPS is not adopted by default.",
 ["MIG gives hardware-level memory isolation with predictable capacity.",
  "Exclusive gives full throughput and no interference.",
  "Time-slicing is zero-setup but has no isolation."],
 "MIG requires a supported GPU SKU and a fixed profile set. MIG reconfiguration requires draining the GPU, which is disruptive. Time-slicing has no VRAM isolation at all: one tenant can exhaust memory and kill another tenant's process. MPS shares a single process address space, so a fault in one tenant can affect the others.",
 "MIG resource names are published by the device plugin (for example a resource per MIG profile) and must be read from the live node rather than assumed.",
 "Time-slicing contention is invisible in the API: a pod scheduled successfully can still fail at runtime with an out-of-memory error caused by a neighbour.",
 "MIG is not reversible into a single full GPU without a drain and reconfigure cycle, and only on MIG-capable hardware.",
 "MIG is the only option that delivers hard VRAM isolation, which the master prompt explicitly requires for multi-tenant GPU sharing. Time-slicing is retained only where the isolation requirement is knowingly waived, and it is labelled as such everywhere it appears."),

(23, "LLM inference platform",
 "Serving engine selection drives VRAM sizing, throughput targets, and the artifact footprint.",
 ["vLLM only.",
  "Triton only.",
  "Multiple engines."],
 "vLLM as the primary production engine, llama.cpp for small or aggressively quantized models and CPU fallback, Triton only if non-LLM model types enter the estate, and NIM evaluated against licence and offline artifact size before any use.",
 ["vLLM has the best throughput and continuous batching for LLMs.",
  "llama.cpp runs tiny models on small hardware with GGUF.",
  "Triton is multi-framework but heavier to run.",
  "NIM removes tuning effort but adds licence terms."],
 "Each engine brings its own model formats, quantization, memory behaviour, and metrics. Supporting several means supporting several artifact sets offline. A model converted for one engine is not directly usable in another.",
 "Inference API port (for example 8000 for an OpenAI-compatible endpoint), DCGM exporter 9400, model store access 443, and the metrics port per engine.",
 "Engine failure affects inference availability only. Autoscaling on queue depth and GPU utilisation is required, and pre-loading models on the node-local NVMe cache avoids cold-start latency.",
 "Engine migration requires model conversion and re-benchmarking. Model conversion is a lossy operation for some quantization schemes.",
 "vLLM covers the primary use case with the best throughput. The others are justified by specific constraints, not by preference."),

(24, "Offline repository and registry design",
 "The environment has no internet, so the distribution architecture is a hard constraint.",
 ["One Nexus for everything.",
  "Harbor for images plus Nexus for packages.",
  "GitLab registry plus Nexus."],
 "Harbor for OCI images and Helm charts (OCI), Nexus for rpm/deb/PyPI/npm/helm-hosted/raw formats, GitLab for source and CI, and Ceph RGW S3 (or MinIO) for AI model weights. One system of record per artifact type, with no duplication.",
 ["Harbor has image-specific features: scanning, replication, retention, immutability, provenance.",
  "Nexus covers the long tail of package formats well.",
  "GitLab registry duplicates Harbor without adding value."],
 "Multiple systems mean multiple auth schemes and multiple backup jobs. The client configuration burden is real: containerd, apt, dnf, pip, Helm, Git, and Ansible each need pointing at the internal source, and TLS trust must be distributed.",
 "Harbor 443 (and 5000 for the registry component), Nexus 443/8081, GitLab 443, RGW 7480, plus the manager ports for the stateful backing services. All in the network matrix.",
 "Registry outage blocks new deployments but not running workloads, provided images are cached on the nodes. A missing transitive dependency discovered mid-deployment is the most likely failure mode, and it is why a full staging dry run is required before production.",
 "Migrating a format from one repository system to another is a re-import plus client reconfiguration. Keeping the mapping in the artifact matrix makes that a scripted operation.",
 "Splitting by artifact type avoids one system doing everything badly, and it keeps the image-specific governance (scan, sign, retain) in the tool that understands images."),

(25, "Vault recovery and avoidance of circular dependencies",
 "The restore path must work when the cluster, the identity provider, and the network are all in a bad state.",
 ["Vault inside the Management Cluster, unsealed with a KMS inside the same cluster.",
  "Vault on dedicated hosts with offline Shamir shares.",
  "Vault with a cloud KMS auto-unseal."],
 "Vault on dedicated hosts with offline Shamir key shares (or an external HSM/KMS that is not in the cluster). Restore order is fixed: Vault first, then identity, then the Management Cluster, then Application Clusters. Argo CD is never the only path to restore a cluster it manages.",
 ["The unseal path does not depend on anything that can be lost in the incident.",
  "The restore path is not circular.",
  "Manual unseal is slower than auto-unseal but has no infrastructure dependency."],
 "Manual unseal needs a documented, practiced procedure with a quorum of custodians. It is a human process during an incident, which is exactly when human processes fail. Auto-unseal needs a KMS outside the cluster, which adds a dependency but removes the human step.",
 "Vault 8200 for the API, 8201/8202 for cluster communication, plus the KMS endpoint if auto-unseal is used.",
 "An extended Vault outage stops secret renewal. Certificates expiring during the outage, and applications that read secrets only at startup, are the two hard failure modes to test.",
 "Restoring a Vault cluster from a snapshot requires the storage snapshot plus the unseal material plus the root token, and they must come from different places. Vault backup and Kubernetes backup are separate procedures; a Velero backup does not include Vault data in this model.",
 "The whole point of the architecture is that a total loss is recoverable with a documented sequence of manual steps and offline material. Every other design choice is subordinate to that."),

 (26, "Kubespray multi-version support",
 "A single pinned Kubespray release is a single point of failure. It pins one Kubernetes, etcd, containerd, CNI and Helm set, and when that release ages out, or when a site needs a Kubernetes version it cannot deploy, the whole estate is blocked on one upgrade. Kubespray maintains parallel release branches, each with its own pinned component versions and its own Ansible and Python compatibility window.",
 ["Support exactly one Kubespray release, the newest.",
 "Support three Kubespray releases.",
 "Support five Kubespray releases in parallel, each fully deployable and offline-capable."],
 "Support five Kubespray release branches in parallel: release-2.28 through release-2.32. Each release gets its own checkout, its own Python virtualenv, its own inventory directory, and its own mirrored artifact set. A cluster is bound to the release that built it, and that binding is recorded in the inventory.",
 ["Covers five consecutive Kubernetes minor versions, so a cluster that must stay on an older version is still deployable and still rebuildable.",
 "A release leaves the supported set only when a fifth successor exists, which keeps the set at five.",
 "Each release is a complete configuration, so a rebuild on an older pinned combination is possible.",
 "Five virtualenvs, five artifact trees and five inventories is a real maintenance cost, and the offline mirror size grows accordingly.",
 "Mixing component versions across releases is not supported, so the inventory must not be shared between them."],
 "Each release's artifacts must be mirrored and pull-verified independently, because the image sets differ per Kubernetes and containerd version. A release that is not mirrored cannot be used to rebuild a cluster, which defeats the purpose of keeping it supported.",
 "Five Kubespray checkouts, five virtualenvs with different Ansible versions, five inventory trees, five files_repo trees, and five Harbor projects. The artifact matrix gains one row set per release.",
 "A cluster moves one Kubernetes minor at a time, using the next-newer release's inventory and virtualenv. Rebuilding a cluster on an older release is a matter of pointing at that release's checkout, inventory and venv, with the same group vars.",
 "The supported set is reduced when a Kubernetes version inside it reaches end of life, or when a critical CVE in a pinned Kubernetes version forces an early exit. Either case is recorded as an ADR amendment with the reason and the date."),

 (27, "Ingress controller portfolio and deprecation policy",
 "One ingress controller is a single point of failure and a single point of lock-in. The community ingress-nginx project was retired in March 2026, which showed concretely what happens when a controller's project ends: deployments keep running on a frozen version with no security fixes and no upgrade path. A portfolio with an explicit lifecycle gives the platform a rehearsed escape route and a second implementation for failover and for Gateway API migration.",
 ["One controller, replaced when its project is retired.",
 "A portfolio with no lifecycle rules.",
 "A bounded portfolio of at most three deployed controllers, each with a stage, a replacement, and a removal date."],
 "A bounded portfolio of at most three deployed controllers, each assigned one of five stages (Candidate, Supported, Deprecated, Removed, Retired upstream), with a dated deprecation schedule and a mandatory replacement named before a controller is deployed. F5 NGINX Ingress Controller and F5 NGINX Gateway Fabric are Supported; Envoy Gateway is Supported as the Gateway API native failover target; everything else is a Candidate. Upstream retirement forces Deprecated immediately, and a critical CVE forces an urgent removal plan.",
 ["A second implementation on a separate address gives a rehearsed failover path and a safe place to land Gateway API traffic.",
 "A named replacement and a removal date mean a deprecation is a plan, not a surprise.",
 "A cap of three keeps the offline artifact footprint and the operational surface bounded.",
 "Three controllers means three sets of images, CRDs, certificates, addresses, admission webhooks and skills.",
 "A controller held in the Deprecated stage still consumes address space, artifacts, and attention."],
 "Each controller runs in its own namespace with its own admission webhook and a namespace-scoped failure policy, so one controller's webhook outage does not block writes for another. The annotation-driven configuration surface must stay disabled: the retired project was explicitly criticised for allowing arbitrary NGINX directives through an annotation, and the replacement must not reintroduce that. A wildcard certificate is issued per controller, so a compromised controller cannot serve a valid certificate for another controller's address.",
 "Per controller: 2-4 images, 1 chart, up to 3 CRDs, 1-2 MetalLB addresses, 2 DNS records, 1 ConfigMap and 1 policy. The Gateway API CRDs are shared. Failure is signalled by a DNS or load-balancer target change, not by a controller feature, and a load-balancer health-check-driven change is preferred over DNS because of the TTL.",
 "Migrating a controller is a staged traffic move, not a big bang: new applications go to the replacement immediately, existing applications move on their next deployment, and the remaining ones are migrated on a deadline. Removal is blocked while any traffic share remains, and a controller is never removed before its replacement has served a full business cycle. The Kubernetes SIG Network ingress2gateway tool assists with the conversion, but it is a utility and its output must be reviewed and tested.",
 "A controller is never deployed without a named replacement and a removal date, and no controller stays Deprecated for more than three months without a recorded exception. The deprecation schedule is anchored to upstream dates where they exist, such as the Envoy Gateway release end-of-life dates."),

(28, "External load balancer architecture",
 "The platform needs a stable, highly available address for the Kubernetes API, the Rancher agent, the Argo CD controller, the CI runners, and the client-facing ingress. The requirement is an active/active pair of Linux nodes running Nginx or HAProxy with Keepalived, deployed with Docker Compose. The tension is that Keepalived implements VRRP, and VRRP elects one master per virtual router id, so a single VIP under VRRP is active/standby by protocol, not by configuration.",
 ["One VIP with Keepalived VRRP, active/standby.",
  "One VIP with the dataplane running active/active on both nodes behind it.",
  "Two VIPs, one per node, with upstream ECMP or BGP balancing between them, plus DNS/GSLB for client-facing names.",
  "A hardware or cloud load balancer."],
 "Tiered design. The dataplane (HAProxy for L4 and active health checks, Nginx for L7 policy and TLS) runs on both edge nodes, containerised with Docker Compose, on the host network, binding the wildcard address with net.ipv4.ip_nonlocal_bind=1 so the socket is held whether or not the node currently owns a VIP. Keepalived manages the addresses with unicast peers. Active/active is delivered at tier 2: each node owns its own VIP and the router balances between them with ECMP or BGP; tier 3 adds DNS with health checks for client-facing names the router cannot balance. Tier 1, a single VRRP-owned VIP, is retained as the fallback when the router cannot balance, and is documented as active/standby rather than active/active.",
 ["The dataplane is always up and serving on both nodes, so the VIP movement is a routing change, not a service start.",
  "Both nodes carry traffic, so losing one halves capacity instead of removing it.",
  "The edge is stateless and rebuilt by Ansible from committed configuration, so it is reconciled by GitOps at the node level.",
  "Two tiers of upstream dependency: the router must support ECMP or BGP for tier 2, and DNS must support health-checked records for tier 3.",
  "VRRP failover is roughly three seconds, and in-flight connections on the failing node reset; the drain window mitigates but does not eliminate it.",
  "Nginx and HAProxy in the same path doubles the component count and the failure surface for no benefit."],
 "The edge is the only host exposed to the untrusted segment, so it runs a minimal image set with no shell access, and the host firewall allows only 80 and 443 inbound. VRRP uses unicast peers because the DMZ segment is assumed to filter multicast; multicast must be confirmed with the network team before use. The dataplane binds the wildcard address and never the VIP, so an address move does not require a container restart, and the VRRP auth_pass and the TLS key are written by Ansible from Vault rather than committed to Git. A keepalived track_script health check stops a node with a broken dataplane from taking an address. SO_REUSEPORT on the Nginx listeners gives per-host worker sharding only; it is not cross-node balancing.",
 "The dataplane binds 80, 443, and the local health port 8443, plus the management-only stats port 8404 on the management address. Keepalived needs IP protocol 112 and the unicast peer port 112 between the edge nodes. The container runtime needs NET_ADMIN, NET_BROADCAST, NET_RAW, and SYS_MODULE for keepalived. Images and configuration are mirrored offline; the edge images are nginx 1.31.8, haproxy 3.2.26, and keepalived 2.4.3, with the Compose file and the configuration in Git.",
 "The edge is stateless, so losing both nodes loses only the edge. Losing one node in tier 2 leaves the surviving node serving its own VIP and the router converging on it. Losing the router's balancing capability in tier 2 degrades to whichever node the router still considers healthy, so the router's health-check configuration is part of the edge's failure model.",
 "Moving from tier 1 to tier 2 requires the network team to add ECMP or BGP for the two VIPs; the edge configuration itself is unchanged apart from a second VIP in keepalived. Moving from tier 2 to a hardware load balancer means pointing the router at it and retiring the edge nodes. The dataplane configuration is portable between Nginx and HAProxy for the L4 role, so the choice is not a one-way door."),
]

TEMPLATE = """# ADR-{num:04d} — {title}

- **Status**: {status}
- **Date**: {date}
- **Deciders**: {deciders}
- **Supersedes / superseded by**: none

## Context

{context}

## Requirements

{requirements}

## Options considered

{options}

## Decision

{decision}

## Rationale and trade-offs

{tradeoffs}

## Security and operational implications

{notes}

## Dependencies

{deps}

## Failure scenarios

{failure}

## Migration considerations

{migration}
"""

for entry in ADRS:
    num, title, context, options, decision = entry[:5]
    tradeoffs = entry[5]
    notes = entry[6]
    deps = entry[7]
    failure = entry[8]
    migration = entry[9]
    if len(entry) > 10:
        # trailing rationale note
        tradeoffs = tradeoffs + [entry[10]]
    body = TEMPLATE.format(
        num=num, title=title,
        status="Accepted (provisional pending Phase 1 review)",
        date="2026-10-22",
        deciders="Platform Architect / SecOps / SRE",
        context=context,
        requirements="See `requirements/requirements-and-assumptions.md` (R-01..R-14, D-01..D-14).",
        options="\n".join(f"- {i+1}. {o}" for i, o in enumerate(options)),
        decision=decision,
        tradeoffs="\n".join(f"- {t}" for t in tradeoffs),
        notes=notes,
        deps=deps,
        failure=failure,
        migration=migration,
    )
    with open(os.path.join(OUT, f"ADR-{num:04d}-{title.lower().replace(' ', '-').replace(',', '').replace('/', '-')}.md"), "w") as fh:
        fh.write(body)

print(f"wrote {len(ADRS)} ADRs to {OUT}")
